<script>
function uploadField(){return{fileName:'',dragActive:false,select(e){const f=e.target.files[0];if(f)this.fileName=f.name},drop(e){this.dragActive=false;const f=e.dataTransfer.files[0];if(!f)return;const d=new DataTransfer();d.items.add(f);this.$refs.file.files=d.files;this.fileName=f.name},clear(){this.$refs.file.value='';this.fileName=''}}}
function applicationForm(){return{submitting:false,submitForm(){if(this.submitting)return;this.submitting=true}}}
</script>
